input.command:
cd /tmp/t4 && echo "--- t4 pointing at big ---"; time (for i in 1 2 3 4 5; do /workspace/executable -g /tmp/big/.git -w /tmp/big >/dev/null 2>&1; done)
echo "--- t4 pointing at big (only -w) ---"; time (for i in 1 2 3 4 5; do /workspace/executable -w /tmp/big >/dev/null 2>&1; done)
echo "--- t4 pointing at big (only -g) ---"; time (for i in 1 2 3 4 5; do /workspace/executable -g /tmp/big/.git >/dev/null 2>&1; done)
cd /tmp/big && echo "--- big pointing at t4 ---"; time (for i in 1 2 3 4 5; do /workspace/executable -g /tmp/t4/.git -w /tmp/t4 >/dev/null 2>&1; done)
echo "--- big with bogus gitdir ---"; time (for i in 1 2 3 4 5; do /workspace/executable -g /tmp/nope/.git -w /tmp/nope >/dev/null 2>&1; done)

cd /tmp/big && SHA=$(git rev-parse HEAD~10)
echo "--- no from (baseline) ---"; time (for i in 1 2 3 4 5; do /workspace/executable >/dev/null 2>&1; done)
echo "--- -f HEAD~10 ---"; time (for i in 1 2 3 4 5; do /workspace/executable -f HEAD~10 >/dev/null 2>&1; done)
echo "--- -f sha10 ---"; time (for i in 1 2 3 4 5; do /workspace/executable -f $SHA >/dev/null 2>&1; done)
echo "--- -t HEAD~4990 ---"; time (for i in 1 2 3 4 5; do /workspace/executable -t HEAD~4990 >/dev/null 2>&1; done)
echo "--- calib: git log full ---"; time (for i in 1 2 3 4 5; do git log --format='%H%n%s%n%b%n==END==' >/dev/null; done)
echo "--- calib: git log HEAD~10.. ---"; time (for i in 1 2 3 4 5; do git log --format='%H%n%s%n%b%n==END==' HEAD~10..HEAD >/dev/null; done)

cd /tmp/big && echo "--- clog baseline ---"; time (for i in 1 2 3 4 5; do /workspace/executable >/dev/null 2>&1; done)
echo "--- git log plain fmt ---"; time (for i in 1 2 3 4 5; do git log --format='%H%n%s%n%b%n==END==' >/dev/null; done)
echo "--- git log -E --grep ---"; time (for i in 1 2 3 4 5; do git log -E --grep='^(feat|fix|docs)' --format='%H%n%s%n%b%n==END==' >/dev/null; done)
echo "--- git log --format only hash ---"; time (for i in 1 2 3 4 5; do git log --format='%H' >/dev/null; done)
echo "--- git log default pretty ---"; time (for i in 1 2 3 4 5; do git log >/dev/null; done)
